function nearSiteName(){for(const n of ['A','B'])if(Math.hypot(player.pos.x-sites[n].x,player.pos.z-sites[n].z)<8)return n;return null}
function endRound(attackerWins,reason){if(roundEnded)return;roundEnded=true;active=false;document.exitPointerLock?.();if(attackerWins)atkScore++;else defScore++;$('atkScore').textContent=atkScore;$('defScore').textContent=defScore;$('resultEyebrow').textContent=`ROUND ${String(round).padStart(2,'0')} COMPLETE`;$('resultTitle').textContent=attackerWins?'SITE SECURED':'LINE HELD';$('resultText').textContent=reason;$('nextRound').textContent='NEXT ROUND →';$('resultOverlay').classList.remove('hidden')}
